import { put, get } from '@vercel/blob';
import { authorized, deny, profileOf } from './_lib.js';

// Topics added by the family (by hand or generated by the teacher).
const pathFor = (p) => (p ? `state/topics-${p}.json` : 'state/topics.json');

async function load(PATH) {
  const r = await get(PATH, { access: 'private', useCache: false }).catch(() => null);
  if (!r || r.statusCode !== 200) return { topics: [] };
  return JSON.parse(await new Response(r.stream).text());
}

export default async function handler(req, res) {
  if (!authorized(req)) return deny(res);
  const PATH = pathFor(profileOf(req));
  try {
    if (req.method === 'GET') return res.status(200).json(await load(PATH));
    if (req.method === 'POST') {
      const b = typeof req.body === 'string' ? JSON.parse(req.body) : req.body;
      const cur = await load(PATH);
      let topics = cur.topics || [];
      if (b?.delete) topics = topics.filter(t => t.id !== String(b.delete));
      else if (b?.topic && typeof b.topic === 'object') {
        const t = b.topic;
        if (!t.id || !t.n || !Array.isArray(t.steps) || !t.steps.length) return res.status(400).json({ code: 'bad_request' });
        topics = topics.filter(x => x.id !== t.id).concat([{ ...t, updated: Date.now() }]);
      } else return res.status(400).json({ code: 'bad_request' });
      const body = JSON.stringify({ topics: topics.slice(-200), updated: Date.now() });
      if (body.length > 3_000_000) return res.status(413).json({ code: 'too_large' });
      await put(PATH, body, { access: 'private', contentType: 'application/json', addRandomSuffix: false, allowOverwrite: true });
      return res.status(200).json({ ok: true, count: topics.length });
    }
    return res.status(405).json({ code: 'method' });
  } catch (e) {
    console.error('topics error', e);
    return res.status(500).json({ code: 'storage' });
  }
}
